<?php require_once __DIR__ . '/../bootstrap.php'; $user=require_auth(); $i=body();$id=(int)($i['id']??0);$q=$pdo->prepare('SELECT user_id FROM log_entries WHERE id=?');$q->execute([$id]);$row=$q->fetch();if(!$row||($user['role']!=='admin'&&(int)$row['user_id']!==(int)$user['id']))respond(false,'Log entry not found.',[],404);if(!clean($i['title']??'')||!clean($i['activity']??''))respond(false,'Title and activity are required.',[],422);$s=$pdo->prepare('UPDATE log_entries SET title=?,log_date=?,time_in=?,time_out=?,activity=?,location=?,category=?,remarks=?,status=? WHERE id=?');$s->execute([clean($i['title']),$i['log_date'],$i['time_in']??null,$i['time_out']??null,clean($i['activity']),clean($i['location']??'')?:null,clean($i['category']??'Other'),clean($i['remarks']??''),$i['status']??'Completed',$id]);respond(true,'Log entry updated successfully.');
